insert into public.portfolio_ai_articles (slug, title, description, category_slug, tags, technologies, published_at, updated_at, reading_time, difficulty, author, featured, cover_emoji, body, sort_order) values ('how-i-use-claude-code-as-my-mentor', 'How I Use Claude Code Every Day — As a Mentor, Not an Autopilot', 'I built a strict-mentor system prompt that refuses to hand me finished code. Here''s why I made AI harder to use, not easier.', 'ai-workflows', ARRAY['Claude Code', 'AI', 'Learning', 'Workflow']::text[], ARRAY['Claude Code', 'Java', 'Spring Boot']::text[], '2026-07-01', null, 7, 'intermediate', 'Hen Heang', true, '🤖', $json$[{"type":"paragraph","text":"Most people use Claude Code to move faster. I use it that way too — but for my learning workspace, I deliberately configured it to slow me down. I maintain a separate repo of study notes with a CLAUDE.md that turns Claude into a strict senior mentor, and the single rule that matters most is: never give me complete working code as a first response."},{"type":"heading","level":2,"text":"Why I made AI harder to use","id":"why-harder"},{"type":"paragraph","text":"Early on, I noticed a pattern: I'd ask Claude to write something, get a working answer in seconds, paste it in, and move on. The code worked. I didn't. Three days later I couldn't explain what SecurityContextHolder actually did in my own JWT filter — I had shipped an explanation I never internalized. That's the real risk of AI-assisted development for someone still building fundamentals: it can produce correct code faster than it produces understanding."},{"type":"callout","variant":"info","title":"The Golden Rule","text":"If I ask \"write me X\", Claude must refuse politely, ask me to attempt it first, and give only a hint or the first step — unless I explicitly say \"SPEED MODE\"."},{"type":"heading","level":2,"text":"Four modes, one system prompt","id":"four-modes"},{"type":"list","items":["LEARNING MODE (default) — explain step by step, always the WHY, then quiz me before moving on.","PAIR MODE — I paste my own code first. Claude finds bugs and explains why, but does not rewrite it for me.","SPEED MODE — only for things I've already mastered. Claude may write boilerplate directly, but first asks me one check question to confirm I actually understand what it's about to generate.","TRANSLATION MODE — Korean ↔ English technical translation, no restrictions. This one exists because I work at a Korean fintech company and read a lot of Korean engineering docs."]},{"type":"paragraph","text":"The mode system exists because \"always explain, never give code\" is too rigid for real work — sometimes I genuinely just need a Redis config and already understand what it does. SPEED MODE is the escape hatch, gated by one honesty check instead of an unlimited one."},{"type":"heading","level":2,"text":"A real session, start to finish","id":"real-session"},{"type":"timeline","steps":[{"label":"Problem","text":"Reviewing a payout endpoint, I couldn't tell if it was safe against an external system retrying the same request."},{"label":"Prompt","text":"\"I'm a Spring Boot developer. In AutoPayController.java, autoPay() calls paymentService.process(req) with no duplicate check. If the caller times out and retries, is this dangerous? Explain the risk only, no rewritten code, 5 sentences max.\""},{"label":"Claude's response","text":"Explained the TOCTOU (time-of-check to time-of-use) race: an exists-check alone isn't enough because two identical retries can both pass the check before either insert commits."},{"label":"My review","text":"I pushed back with an \"I think\" prompt: \"I think adding an existsByExternalTxId() check at the top fixes it. Is that correct?\" Claude said no — that closes the common case but not the race window, and asked what closes a race at the database level instead of just the application level."},{"label":"Final understanding","text":"I landed on the actual fix myself: a UNIQUE constraint on the external transaction ID column, with the application catching the constraint violation and returning the existing result instead of erroring."},{"label":"Lesson learned","text":"An application-level exists() check is a fast path, not a guarantee. The database constraint is the real guarantee. I now check for a UNIQUE index before approving any payment-adjacent PR."}]},{"type":"paragraph","text":"That session produced zero pasted code. What it produced was a rule I now apply on every payment-related review, written up in [[idempotency-timeout-is-not-failure]]."},{"type":"heading","level":2,"text":"What this looks like week to week","id":"week-to-week"},{"type":"paragraph","text":"Every session starts the same way: Claude reads a PROGRESS.md file tracking my current topic, weak spots, and quiz history, then opens with a warm-up — 1-2 questions from something I got wrong last time, active recall style, before I'm allowed to ask about anything new. Every session ends with a Feynman check: explain the concept back in my own words, corrected if needed, saved to a notes folder. Nothing gets marked \"done\" if my last quiz grade was WEAK or FAIL."},{"type":"callout","variant":"best-practice","title":"The habit this builds","text":"AI is a collaborator, not a replacement. I stay responsible for the architecture decision, the security tradeoff, and the business logic — Claude is very good at making sure I actually understand them before I ship them."}]$json$::jsonb, 0) on conflict (slug) do nothing;
insert into public.portfolio_ai_articles (slug, title, description, category_slug, tags, technologies, published_at, updated_at, reading_time, difficulty, author, featured, cover_emoji, body, sort_order) values ('prompt-engineering-for-backend-developers', 'Prompt Engineering for Backend Developers: The 3-Part Rule', 'Context, Task, Constraint — the one rule I check before sending any prompt, plus ten techniques that turned vague answers into precise ones.', 'prompt-engineering', ARRAY['Prompt Engineering', 'AI', 'Claude Code', 'ChatGPT']::text[], ARRAY['Claude Code', 'ChatGPT', 'AI']::text[], '2026-06-30', null, 9, 'beginner', 'Hen Heang', true, '💬', $json$[{"type":"paragraph","text":"I used to write prompts like \"explain this code\" or \"fix my bug\" and wonder why the answer was too generic to use. Every good prompt actually needs three parts, and missing any one of them produces a bad result."},{"type":"table","headers":["Part","Question","Example"],"rows":[["Context","Who are you + what situation?","\"I am a Spring Boot developer building JWT auth\""],["Task","What exactly do you want?","\"Explain line 49 in JWTAuthenticationFilter.java\""],["Constraint","How do you want the answer?","\"5 sentences, no code, beginner level\""]]},{"type":"heading","level":2,"text":"Point to an exact location, not \"this code\"","id":"exact-location"},{"type":"paragraph","text":"\"Explain this code\" forces the model to guess what matters. Exact file + exact line + the pasted line gets you an answer aimed at the right thing."},{"type":"callout","variant":"warning","title":"Bad vs. good","text":"Bad: \"Why do we check authentication == null?\" — Good: \"In JWTAuthenticationFilter.java line 51: if (userEmail != null && authentication == null) — why do we check authentication == null? What happens if we remove it? One paragraph, no code.\""},{"type":"heading","level":2,"text":"Iterative prompting beats one giant prompt","id":"iterative"},{"type":"paragraph","text":"One big question produces one shallow answer. Four small ones build real understanding:"},{"type":"list","ordered":true,"items":["What does this do? (basic understanding)","Go deeper on one specific part.","\"I think X is true. Is that correct?\" — test yourself.","Ask for a real scenario or edge case."]},{"type":"heading","level":2,"text":"Constrain the output, every time","id":"constrain"},{"type":"paragraph","text":"Without a constraint the model gives you everything it knows, and you spend more time reading than you saved by asking. \"Answer in 3 sentences max\", \"no code examples\", \"only explain X, ignore Y and Z\" are the highest-leverage words in any prompt."},{"type":"heading","level":2,"text":"The \"I think\" prompt","id":"i-think"},{"type":"paragraph","text":"After an explanation, I write: \"I think [my understanding]. Is that correct? Just yes or no, then one sentence why.\" This forces me to actually think before I move on, and it shows the model exactly where I misunderstood — so the correction is narrow instead of a full re-explanation."},{"type":"heading","level":2,"text":"Role prompting for honest reviews","id":"role-prompting"},{"type":"quote","text":"Act as a strict senior Spring Boot developer reviewing my code. Do not rewrite it. Only point out what is wrong and ask me how I would fix it."},{"type":"paragraph","text":"The role changes the tone of the response. A default assistant tends toward encouragement; a \"strict senior reviewer\" role gives harder, more honest feedback — closer to what an actual PR review looks like."},{"type":"heading","level":2,"text":"One topic per prompt","id":"one-topic"},{"type":"paragraph","text":"\"Explain JWT, SecurityContextHolder, and how filters work in Spring\" in one message gets you three shallow paragraphs. Three separate prompts, one topic each, gets you three focused, usable answers — and each one is small enough to actually read carefully."},{"type":"callout","variant":"tip","title":"Checklist before sending any prompt","text":"Context given? Specific task with exact file/line? A length or format constraint? Exactly one topic? Exact code pasted, not summarized? If any box is unchecked, fix the prompt before sending."},{"type":"paragraph","text":"These techniques cost nothing extra to apply and the difference in answer quality is not subtle — a prompt with all three parts routinely replaces three or four follow-up messages."}]$json$::jsonb, 1) on conflict (slug) do nothing;
insert into public.portfolio_ai_articles (slug, title, description, category_slug, tags, technologies, published_at, updated_at, reading_time, difficulty, author, featured, cover_emoji, body, sort_order) values ('mybatis-dynamic-sql-tags-that-matter', 'MyBatis Dynamic SQL: The Tags That Actually Matter', 'if, where, set, foreach, and choose cover almost every real query I write. A field guide with the patterns I reach for most.', 'backend-notes', ARRAY['MyBatis', 'SQL', 'Spring Boot', 'Java']::text[], ARRAY['Java', 'Spring Boot', 'MyBatis', 'PostgreSQL']::text[], '2026-06-15', null, 6, 'intermediate', 'Hen Heang', false, '🧮', $json$[{"type":"paragraph","text":"Dynamic SQL is how MyBatis lets you build safe, maintainable queries without manual string concatenation. Eight tags cover almost everything I actually write in production mapper XML."},{"type":"table","headers":["Tag","Use"],"rows":[["<if>","Add a condition only when a value exists"],["<choose>/<when>/<otherwise>","Branch logic (if-else)"],["<where>","Auto-adds WHERE and strips a leading AND/OR"],["<set>","Auto-builds SET for update statements"],["<foreach>","Iterate a list/map for IN or batch SQL"],["<trim>","Custom prefix/suffix cleanup"],["<sql> + <include>","Reusable SQL fragment"],["<bind>","Runtime variable, often for LIKE"]]},{"type":"heading","level":2,"text":"<if> inside <where>","id":"if-where"},{"type":"code","language":"xml","filename":"UserMapper.xml","code":"<select id=\"searchUsers\" resultMap=\"UserMap\">\n  SELECT * FROM users\n  <where>\n    <if test=\"username != null and username != ''\">\n      AND username = #{username}\n    </if>\n    <if test=\"status != null\">\n      AND status = #{status}\n    </if>\n  </where>\n</select>"},{"type":"heading","level":2,"text":"<choose> for controlled sorting","id":"choose-sorting"},{"type":"code","language":"xml","code":"ORDER BY\n<choose>\n  <when test=\"sortBy == 'username'\">username</when>\n  <when test=\"sortBy == 'createdAt'\">created_at</when>\n  <otherwise>id</otherwise>\n</choose>\n<choose>\n  <when test=\"sortOrder == 'ASC'\">ASC</when>\n  <otherwise>DESC</otherwise>\n</choose>"},{"type":"callout","variant":"best-practice","title":"Never string-concat a sort column","text":"Sort/order parameters come straight from query strings. Whitelisting them through <choose> instead of interpolating them directly is what keeps a \"sortBy\" parameter from becoming a SQL injection vector."},{"type":"heading","level":2,"text":"<foreach> for IN-lists and batch inserts","id":"foreach"},{"type":"code","language":"xml","code":"<select id=\"findByIds\" resultMap=\"UserMap\">\n  SELECT * FROM users\n  WHERE id IN\n  <foreach collection=\"ids\" item=\"id\" open=\"(\" close=\")\" separator=\",\">\n    #{id}\n  </foreach>\n</select>\n\n<insert id=\"batchInsert\">\n  INSERT INTO users (username, email, status) VALUES\n  <foreach collection=\"users\" item=\"user\" separator=\",\">\n    (#{user.username}, #{user.email}, #{user.status})\n  </foreach>\n</insert>"},{"type":"heading","level":2,"text":"<set> for partial updates","id":"set-update"},{"type":"code","language":"xml","code":"<update id=\"dynamicUpdate\">\n  UPDATE users\n  <set>\n    <if test=\"username != null and username != ''\">username = #{username},</if>\n    <if test=\"email != null and email != ''\">email = #{email},</if>\n    <if test=\"status != null\">status = #{status},</if>\n  </set>\n  WHERE id = #{id}\n</update>"},{"type":"paragraph","text":"<set> does the same trailing-comma cleanup for UPDATE that <where> does for leading AND/OR — without it, a partial update with only one changed field would end in a dangling comma and fail to compile."},{"type":"heading","level":2,"text":"Reusable fragments","id":"fragments"},{"type":"code","language":"xml","code":"<sql id=\"userColumns\">id, username, email, status, created_at</sql>\n\n<select id=\"findAll\" resultMap=\"UserMap\">\n  SELECT <include refid=\"userColumns\"/>\n  FROM users\n  ORDER BY id DESC\n</select>"},{"type":"paragraph","text":"Every one of these patterns also has an index-usage cost — see [[mapper-xml-query-review-checklist]] for the review checklist I run against every mapper change before it ships."}]$json$::jsonb, 2) on conflict (slug) do nothing;
insert into public.portfolio_ai_articles (slug, title, description, category_slug, tags, technologies, published_at, updated_at, reading_time, difficulty, author, featured, cover_emoji, body, sort_order) values ('mapper-xml-query-review-checklist', 'The Checklist I Run on Every MyBatis Query Before It Ships', 'The database will run almost any query — slowly. A five-step self-review that catches index misses and type mismatches before they hit production.', 'backend-notes', ARRAY['MyBatis', 'SQL', 'PostgreSQL', 'Performance', 'Code Review']::text[], ARRAY['Java', 'MyBatis', 'PostgreSQL']::text[], '2026-06-20', null, 8, 'advanced', 'Hen Heang', true, '🔍', $json$[{"type":"paragraph","text":"Nothing warns you at compile time that your WHERE clause skips every index. A query with a typo fails loudly; a query with a bad execution plan just runs slowly, quietly, until the table is big enough to notice. This is the checklist I run on myself immediately after writing or changing any MyBatis query, while the intent is still fresh."},{"type":"heading","level":2,"text":"Step 1 — Look up metadata for every table first","id":"step-1"},{"type":"paragraph","text":"Extract every table from the query — FROM, JOIN, INSERT INTO, UPDATE, and tables hiding inside subqueries, which are the easiest to miss. For each one, check its indexes, PK/UNIQUE constraints, and the real data_type of any column headed into a function call."},{"type":"callout","variant":"info","text":"You cannot judge whether a WHERE clause uses an index without knowing which indexes exist. Guessing from the column name (\"it's called USER_ID, surely it's indexed\") is exactly how slow queries reach production."},{"type":"heading","level":2,"text":"Step 2 — The function-signature check","id":"step-2"},{"type":"paragraph","text":"For every SQL function call — TO_CHAR, TO_DATE, CAST, SUBSTRING, LPAD, concatenation, arithmetic — confirm the argument types actually exist as an overload in your database engine. This one bites people migrating from Oracle to PostgreSQL specifically."},{"type":"code","language":"sql","code":"-- fails at runtime if REG_DT is varchar 'YYYYMMDD'\nTO_CHAR(REG_DT, 'YYYY.MM.DD')\n\n-- varchar -> date -> formatted text\nTO_CHAR(TO_DATE(REG_DT, 'YYYYMMDD'), 'YYYY.MM.DD')"},{"type":"callout","variant":"warning","title":"The classic failure","text":"PostgreSQL has TO_CHAR(timestamp, text) and TO_CHAR(numeric, text) — but no TO_CHAR(varchar, text). It compiles fine in your head because Oracle allows it. PostgreSQL will fail at runtime with \"function to_char(character varying, unknown) does not exist\"."},{"type":"heading","level":2,"text":"Step 3 — Analyze every dynamic SQL branch, not just the one you tested","id":"step-3"},{"type":"paragraph","text":"A query with <if>/<choose>/<foreach>/<where>/<set> is really N different queries wearing one id. Write out the actual SQL for every branch and check index usage per branch — the branch with the indexed condition may be fast while the branch without it does a full table scan. You tested one branch in dev; production runs all of them."},{"type":"list","items":["A skipped <if> that removes the only indexed condition creates a full-scan branch — decide whether that branch is ever hit with real data volume.","<foreach> IN-lists with 100+ items are worth reconsidering as a temp-table JOIN instead."]},{"type":"heading","level":2,"text":"Step 4 — Position of user-defined functions","id":"step-4"},{"type":"paragraph","text":"A function in the WHERE clause runs on every row before filtering — the index on that column can't help. The same function in the SELECT list only runs on rows that already survived the WHERE. Moving a function from WHERE to SELECT (or restructuring the filter) can change cost by orders of magnitude."},{"type":"heading","level":2,"text":"Step 5 — When to escalate to EXPLAIN ANALYZE","id":"step-5"},{"type":"paragraph","text":"Even when every static check passes, flag the query for a deeper look when any of these is true: three or more dynamic SQL branches, a user-defined function in WHERE, four or more joined tables, or a large read with no LIMIT. Self-review catches structural mistakes; it can't predict what the query planner will actually do against production-sized data."},{"type":"callout","variant":"best-practice","text":"If this checklist changes a query, put the before/after in the PR description. The next reviewer — or future me — should not have to re-derive why the query looks the way it does."}]$json$::jsonb, 3) on conflict (slug) do nothing;
insert into public.portfolio_ai_articles (slug, title, description, category_slug, tags, technologies, published_at, updated_at, reading_time, difficulty, author, featured, cover_emoji, body, sort_order) values ('idempotency-timeout-is-not-failure', 'Idempotency: "Timeout Is Not Failure — It''s an Unknown Outcome"', 'A production incident from a duplicate payout, and the UNIQUE constraint that actually closes the race an exists() check can''t.', 'architecture', ARRAY['Architecture', 'Java', 'Spring Boot', 'PostgreSQL', 'System Design']::text[], ARRAY['Java', 'Spring Boot', 'PostgreSQL']::text[], '2026-06-22', null, 6, 'advanced', 'Hen Heang', true, '🏗️', $json$[{"type":"paragraph","text":"Every payment, payout, or approval endpoint that an external system calls needs to answer one question correctly: what happens when the caller retries the exact same request? Networks deliver \"at least once\" in practice — a caller's timeout does not mean your server failed to process the request. It may have succeeded after the caller gave up, and the caller will retry, because it has to."},{"type":"callout","variant":"warning","title":"The anti-pattern","text":"An endpoint that processes a payout with no duplicate-transaction check will, on a retried request, process the same payout twice."},{"type":"code","language":"java","filename":"AutoPayController.java","code":"// external caller times out and retries -> processed twice\n@PostMapping(\"/pay/auto\")\npublic Response autoPay(@RequestBody AutoPayRequest req) {\n    paymentService.process(req); // no duplicate-transaction check\n    return Response.ok();\n}"},{"type":"heading","level":2,"text":"Why the exists() check alone isn't enough","id":"exists-not-enough"},{"type":"paragraph","text":"The intuitive fix is to check whether the external transaction ID has already been processed before doing the work. That helps the common case, but it does not close the actual race: two identical requests can arrive at nearly the same moment. Both run existsByExternalTxId(), both see \"not found\", both insert — duplicate payout anyway. This is a TOCTOU race: time-of-check to time-of-use."},{"type":"heading","level":2,"text":"The real fix: a UNIQUE constraint","id":"unique-constraint"},{"type":"code","language":"java","filename":"AutoPayController.java","code":"@PostMapping(\"/pay/auto\")\npublic Response autoPay(@RequestBody AutoPayRequest req) {\n    // 1. fast path: check the external transaction id first\n    if (paymentService.existsByExternalTxId(req.getExternalTxId())) {\n        return Response.duplicate(req.getExternalTxId()); // return the EXISTING result\n    }\n    // 2. UNIQUE constraint + INSERT closes the race window\n    paymentService.processWithIdempotency(req);\n    return Response.ok();\n}"},{"type":"paragraph","text":"The UNIQUE index on the external transaction ID column is the guarantee, not the exists() check — the second INSERT fails at the database level regardless of timing. The application catches that unique-violation and returns the existing result instead of erroring, so a retried request is idempotent from the caller's point of view."},{"type":"callout","variant":"best-practice","title":"Rule of thumb","text":"The exists() check is a fast path for the common case. The database constraint is the guarantee for the race case. You need both — the check for latency, the constraint for correctness."},{"type":"heading","level":2,"text":"The second half of the same incident: unbounded queues","id":"unbounded-queues"},{"type":"paragraph","text":"A related failure mode from the same incident class: async jobs (Kafka consumers, @Async work, notification retries) that accumulate failed items with no retry limit, no TTL, and no cleanup batch. Each failed item is tiny — day one, fifty stuck rows, nobody notices. By day ninety it's two million rows, the polling query that re-reads them slows down, memory for the batch grows, and the system dies. Often the system that dies is not the one that caused the failures."},{"type":"list","items":["Cap retries with a retry_count column and move exhausted items to a dead-letter queue.","Move items older than N days to a separate table so the live queue stays small.","Alarm on an accumulation threshold (e.g. pending-send count > N) — don't wait to notice it manually."]},{"type":"callout","variant":"info","text":"Any queue that can grow must have a bounded size and an alarm. Unbounded growth is just an outage on a delay."}]$json$::jsonb, 4) on conflict (slug) do nothing;
insert into public.portfolio_ai_articles (slug, title, description, category_slug, tags, technologies, published_at, updated_at, reading_time, difficulty, author, featured, cover_emoji, body, sort_order) values ('thymeleaf-from-th-text-to-fragments', 'Thymeleaf for Spring Boot: From th:text to Fragments', 'A practical path through Thymeleaf — basic attribute binding, object selection, and the fragment pattern that kills copy-pasted navbars.', 'backend-notes', ARRAY['Spring Boot', 'Java', 'Thymeleaf']::text[], ARRAY['Java', 'Spring Boot']::text[], '2026-06-10', null, 5, 'beginner', 'Hen Heang', false, '🍃', $json$[{"type":"paragraph","text":"Thymeleaf is Spring Boot's default server-side template engine — the natural successor to JSP, and tightly integrated with the rest of the framework. Three layers cover almost everything I use it for."},{"type":"heading","level":2,"text":"Layer 1 — basic syntax","id":"basic-syntax"},{"type":"code","language":"html","code":"<p th:text=\"${user.name}\">Default Name</p>\n<input type=\"text\" th:value=\"${user.email}\" />\n\n<tr th:each=\"note : ${notes}\">\n    <td th:text=\"${note.title}\">Title</td>\n</tr>\n\n<div th:if=\"${user.isAdmin}\">Admin Panel</div>"},{"type":"heading","level":2,"text":"Layer 2 — patterns from real projects","id":"real-project-patterns"},{"type":"paragraph","text":"th:object plus the *{} shorthand binds a form to a specific object without repeating its name on every field:"},{"type":"code","language":"html","code":"<form th:object=\"${member}\">\n    <input type=\"text\" th:field=\"*{name}\" />\n</form>\n\n<a th:href=\"@{/notes/view(id=${note.id})}\">View Note</a>\n\n<span th:text=\"|Welcome, ${user.name}!|\"></span>"},{"type":"heading","level":2,"text":"Layer 3 — fragments kill copy-pasted navbars","id":"fragments"},{"type":"code","language":"html","code":"<!-- footer.html -->\n<footer th:fragment=\"copy\"> &copy; 2026 dev-notes </footer>\n\n<!-- main.html -->\n<div th:replace=\"~{footer :: copy}\"></div>"},{"type":"paragraph","text":"Combined with the Layout Dialect for a decorator-style shared page shell, and sec:authorize for role-based visibility, fragments are what turn a handful of near-identical pages into one navbar defined once."},{"type":"callout","variant":"tip","text":"Need a Java value inside inline JavaScript? [[${user.id}]] inlining is safer than string-building a <script> tag by hand."}]$json$::jsonb, 5) on conflict (slug) do nothing;

insert into public.portfolio_ai_prompts (prompt_id, title, category, description, prompt, expected_output, best_practices, tags, sort_order) values ('explain-exact-line', 'Explain an exact line, not "this code"', 'backend', 'Get a focused explanation of one line instead of a generic walkthrough of the whole file.', 'I know basic Spring Boot but I have never used SecurityContextHolder before. In JWTAuthenticationFilter.java line 51: `if (userEmail != null && authentication == null)` — why do we check `authentication == null`? What happens if we remove it? One paragraph, no code.', 'A short, specific paragraph explaining the exact condition — not a general JWT tutorial.', ARRAY['State your level on this specific topic, not your overall experience.', 'Paste the exact line and give the file name.', 'Add a length constraint so the answer stays scannable.']::text[], ARRAY['Claude Code', 'Spring Boot', 'Java']::text[], 0) on conflict (prompt_id) do nothing;
insert into public.portfolio_ai_prompts (prompt_id, title, category, description, prompt, expected_output, best_practices, tags, sort_order) values ('root-cause-no-rewrite', 'Root-cause a bug without a rewrite', 'bug-fixing', 'Force a diagnosis instead of a silent fix, so you understand the cause before touching the code.', 'I am a Spring Boot developer. In UserService.java line 32, I get a NullPointerException on `user.getEmail()`. What is the root cause? Do not rewrite the code.', 'A root-cause explanation (e.g. an unguarded Optional or a missing null check upstream) without a code diff.', ARRAY['Explicitly say "do not rewrite the code" — otherwise most assistants default to a fix.', 'Give the exact exception and the exact line.', 'Ask a follow-up for the fix only after you''ve confirmed you understand the cause.']::text[], ARRAY['Java', 'Debugging']::text[], 1) on conflict (prompt_id) do nothing;
insert into public.portfolio_ai_prompts (prompt_id, title, category, description, prompt, expected_output, best_practices, tags, sort_order) values ('strict-senior-reviewer', 'Strict senior reviewer, no rewrites', 'code-review', 'Role-prompting to get harder, more honest feedback than a default assistant tone gives.', 'Act as a strict senior Spring Boot developer reviewing my code. Do not rewrite it. Only point out what is wrong and ask me how I would fix it.', 'A list of concrete issues (correctness, security, style) each ending in a question, not a solution.', ARRAY['The role changes the tone — a "strict senior reviewer" won''t soften bad news.', 'Pair with "do not rewrite" or you''ll get a diff back instead of a review.', 'Use this before opening a real PR, not after — catch issues while they''re cheap to fix.']::text[], ARRAY['Code Review', 'Spring Boot']::text[], 2) on conflict (prompt_id) do nothing;
insert into public.portfolio_ai_prompts (prompt_id, title, category, description, prompt, expected_output, best_practices, tags, sort_order) values ('sql-concept-one-example', 'Explain a SQL concept with exactly one example', 'database', 'Constrain the domain so the example is directly reusable, instead of getting five generic ones.', 'I know basic SQL but never used indexes. Explain a B-tree index with ONE banking example (account balance lookups). Short answer, no history.', 'One concrete, domain-relevant example — not a general index taxonomy.', ARRAY['Ask for exactly one example, not "examples" — you''ll get five generic ones otherwise.', 'Specify the domain (banking, payments) so the example matches your actual codebase.', 'Add "no history" or "no background" if you already know the basics.']::text[], ARRAY['SQL', 'PostgreSQL', 'Database']::text[], 3) on conflict (prompt_id) do nothing;
insert into public.portfolio_ai_prompts (prompt_id, title, category, description, prompt, expected_output, best_practices, tags, sort_order) values ('i-think-check', 'The "I think" understanding check', 'learning', 'Test your own understanding instead of passively reading another explanation.', 'I think we check `authentication == null` because the filter could otherwise run twice per request and overwrite a valid session. Is that correct? Just yes or no, then one sentence why.', 'A direct yes/no plus a one-sentence correction or confirmation — not a re-explanation.', ARRAY['Write your own understanding first, in your own words, before asking.', 'Ask for yes/no plus one sentence — a full re-explanation defeats the point.', 'Use this right after any explanation, not the next day, while it''s still fresh.']::text[], ARRAY['Learning', 'Claude Code']::text[], 4) on conflict (prompt_id) do nothing;
insert into public.portfolio_ai_prompts (prompt_id, title, category, description, prompt, expected_output, best_practices, tags, sort_order) values ('mybatis-branch-review', 'Review every branch of a dynamic MyBatis query', 'database', 'Force branch-by-branch index analysis instead of judging only the branch you happen to test.', 'Here is a MyBatis mapper with `<if>` and `<choose>` blocks [paste XML]. Write out the actual SQL for each possible branch, and for each one tell me whether it can use an existing index on `users(status, created_at)`. Do not rewrite the mapper.', 'One resolved SQL statement per branch combination, each labeled with its index usage (index scan vs. full scan).', ARRAY['Paste the full mapper block, not a summary — branch analysis needs the exact conditions.', 'State the indexes that exist so the model isn''t guessing at schema.', 'Ask specifically for branches, not just "is this query fast" — a fast happy-path branch can hide a slow fallback branch.']::text[], ARRAY['MyBatis', 'SQL', 'Performance']::text[], 5) on conflict (prompt_id) do nothing;
insert into public.portfolio_ai_prompts (prompt_id, title, category, description, prompt, expected_output, best_practices, tags, sort_order) values ('idempotency-check', 'Check a payment endpoint for idempotency', 'system-design', 'Ask specifically about retry-safety, the failure mode that''s easy to miss in a normal review.', 'I am reviewing a Spring Boot endpoint that an external system calls and retries on timeout: [paste controller method]. If the exact same request arrives twice, what happens? Explain the risk only, no rewritten code, 5 sentences max.', 'An explanation of what happens on a duplicate/retried request, including whether an exists-check alone would be sufficient.', ARRAY['Say explicitly that the caller retries on timeout — this is the trigger condition that matters.', 'Ask "what happens" before asking "how do I fix it" — understand the failure before patching it.', 'Follow up by asking what closes the race at the database level, not just the application level.']::text[], ARRAY['Architecture', 'Spring Boot', 'System Design']::text[], 6) on conflict (prompt_id) do nothing;
insert into public.portfolio_ai_prompts (prompt_id, title, category, description, prompt, expected_output, best_practices, tags, sort_order) values ('iterative-four-step', 'Iterative 4-step understanding builder', 'learning', 'Break one big topic into four small prompts instead of one giant question.', 'Prompt 1: What does `jwtService.isTokenValid()` do at a high level? Prompt 2 (after reading the answer): Go deeper on how it checks expiry specifically. Prompt 3: I think it also checks the signature — is that correct? Prompt 4: Give me one real scenario where this method returns false unexpectedly.', 'Four short, focused answers that build on each other, instead of one long answer covering everything at once.', ARRAY['Send these as four separate messages, not one combined prompt.', 'Read and absorb each answer before sending the next prompt.', 'Save the final scenario (prompt 4) as a test case — it''s usually a real edge case worth covering.']::text[], ARRAY['Learning', 'Claude Code']::text[], 7) on conflict (prompt_id) do nothing;
insert into public.portfolio_ai_prompts (prompt_id, title, category, description, prompt, expected_output, best_practices, tags, sort_order) values ('negative-constraint-refactor', 'Refactor review with a negative constraint', 'refactoring', 'Tell the model what NOT to touch so a refactor suggestion doesn''t balloon into a rewrite of unrelated code.', 'In PaymentService.java, the `process()` method is doing too much. Suggest how to split it into smaller methods. Do not touch the transaction annotation or the logging calls — explain only the split, no full file rewrite.', 'A proposed method breakdown (names + responsibilities) that respects the stated boundaries.', ARRAY['Name exactly what must stay untouched — transaction boundaries and logging are common casualties of well-meaning refactors.', 'Ask for the plan before the code — review the shape of the split first.', 'Apply the split yourself in small commits rather than pasting a full rewritten file.']::text[], ARRAY['Refactoring', 'Java', 'Spring Boot']::text[], 8) on conflict (prompt_id) do nothing;
insert into public.portfolio_ai_prompts (prompt_id, title, category, description, prompt, expected_output, best_practices, tags, sort_order) values ('api-design-consistency', 'Check a new endpoint against existing API conventions', 'api-design', 'Catch inconsistency with your own codebase''s conventions, which generic advice can''t see.', 'Here are two existing endpoints from my API [paste both]. Here is a new endpoint I''m about to add [paste it]. Does the new one follow the same response-wrapper and error-handling pattern as the existing two? List only the inconsistencies.', 'A short list of concrete deviations (status codes, field naming, wrapper shape) — not general REST advice.', ARRAY['Always paste real examples from your own codebase — generic REST rules miss project-specific conventions.', 'Ask for inconsistencies only, not a full redesign.', 'Do this before merging, not after — a wrapper mismatch is cheap to fix pre-merge and annoying post-merge.']::text[], ARRAY['API Design', 'REST', 'Spring Boot']::text[], 9) on conflict (prompt_id) do nothing;

insert into public.portfolio_ai_snippets (snippet_id, title, language, code, tags, explanation, sort_order) values ('mybatis-dynamic-where', 'MyBatis Dynamic Search with <where>', 'xml', '<select id="searchUsers" resultMap="UserMap">
  SELECT * FROM users
  <where>
    <if test="username != null and username != ''''">
      AND username = #{username}
    </if>
    <if test="status != null">
      AND status = #{status}
    </if>
  </where>
</select>', ARRAY['MyBatis', 'SQL']::text[], '<where> only inserts WHERE if at least one <if> matched, and strips a leading AND/OR automatically — so you never hand-manage the boolean edge case of zero active filters.', 0) on conflict (snippet_id) do nothing;
insert into public.portfolio_ai_snippets (snippet_id, title, language, code, tags, explanation, sort_order) values ('mybatis-batch-insert', 'MyBatis Batch Insert with <foreach>', 'xml', '<insert id="batchInsert">
  INSERT INTO users (username, email, status) VALUES
  <foreach collection="users" item="user" separator=",">
    (#{user.username}, #{user.email}, #{user.status})
  </foreach>
</insert>', ARRAY['MyBatis', 'SQL', 'Performance']::text[], 'One round trip instead of N. Keep IN-lists under ~100 items with this pattern — beyond that, a temp-table JOIN is usually faster.', 1) on conflict (snippet_id) do nothing;
insert into public.portfolio_ai_snippets (snippet_id, title, language, code, tags, explanation, sort_order) values ('mybatis-partial-update', 'MyBatis Partial Update with <set>', 'xml', '<update id="dynamicUpdate">
  UPDATE users
  <set>
    <if test="username != null and username != ''''">username = #{username},</if>
    <if test="email != null and email != ''''">email = #{email},</if>
    <if test="status != null">status = #{status},</if>
  </set>
  WHERE id = #{id}
</update>', ARRAY['MyBatis', 'SQL']::text[], '<set> strips the trailing comma automatically, so an update with only one changed field doesn''t fail to compile with a dangling comma.', 2) on conflict (snippet_id) do nothing;
insert into public.portfolio_ai_snippets (snippet_id, title, language, code, tags, explanation, sort_order) values ('idempotent-payment-endpoint', 'Idempotent Payment Endpoint', 'java', '@PostMapping("/pay/auto")
public Response autoPay(@RequestBody AutoPayRequest req) {
    // 1. fast path: check the external transaction id first
    if (paymentService.existsByExternalTxId(req.getExternalTxId())) {
        return Response.duplicate(req.getExternalTxId());
    }
    // 2. UNIQUE constraint + INSERT closes the race window
    //    catch the constraint violation and return the existing result
    return paymentService.processWithIdempotency(req);
}', ARRAY['Spring Boot', 'Architecture', 'PostgreSQL']::text[], 'The exists() check is a fast path for the common case; the UNIQUE constraint on external_tx_id is the actual guarantee, because it closes the TOCTOU race between two near-simultaneous retries.', 3) on conflict (snippet_id) do nothing;
insert into public.portfolio_ai_snippets (snippet_id, title, language, code, tags, explanation, sort_order) values ('thymeleaf-fragment', 'Thymeleaf Reusable Fragment', 'html', '<!-- footer.html -->
<footer th:fragment="copy"> &copy; 2026 dev-notes </footer>

<!-- main.html -->
<div th:replace="~{footer :: copy}"></div>', ARRAY['Spring Boot', 'Thymeleaf']::text[], 'th:fragment + th:replace is the decorator pattern for shared UI (navbar, footer) — define once, include everywhere, no copy-pasted markup drifting out of sync.', 4) on conflict (snippet_id) do nothing;
insert into public.portfolio_ai_snippets (snippet_id, title, language, code, tags, explanation, sort_order) values ('postgres-varchar-to-date', 'Safe TO_CHAR on a varchar date column', 'sql', '-- fails at runtime if REG_DT is varchar ''YYYYMMDD''
-- TO_CHAR(REG_DT, ''YYYY.MM.DD'')

-- varchar -> date -> formatted text
SELECT TO_CHAR(TO_DATE(REG_DT, ''YYYYMMDD''), ''YYYY.MM.DD'')
FROM users;', ARRAY['PostgreSQL', 'SQL']::text[], 'PostgreSQL has no TO_CHAR(varchar, text) overload — code that compiled fine in Oracle fails at runtime here. Cast through TO_DATE first.', 5) on conflict (snippet_id) do nothing;
;
